              end
          end,
    B12 = if F12 =:= undefined -> B11;
             true ->
                 case id(F12, TrUserData) of
                     {gold, TF12} -> begin TrTF12 = id(TF12, TrUserData), e_type_int32(TrTF12, <<B11/binary, 96>>, TrUserData) end;
                     {coupon, TF12} -> begin TrTF12 = id(TF12, TrUserData), e_type_string(TrTF12, <<B11/binary, 106>>, TrUserData) end;
