-compile({nowarn_unused_function,e_type_sint/3}).
e_type_sint(Value, Bin, _TrUserData) when Value >= 0 -> e_varint(Value * 2, Bin);
e_type_sint(Value, Bin, _TrUserData) -> e_varint(Value * -2 - 1, Bin).

-compile({nowarn_unused_function,e_type_int32/3}).
e_type_int32(Value, Bin, _TrUserData) when 0 =< Value, Value =< 127 -> <<Bin/binary, Value>>;
e_type_int32(Value, Bin, _TrUserData) ->
    <<N:64/unsigned-native>> = <<Value:64/signed-native>>,
    e_varint(N, Bin).

-compile({nowarn_unused_function,e_type_int64/3}).
e_type_int64(Value, Bin, _TrUserData) when 0 =< Value, Value =< 127 -> <<Bin/binary, Value>>;
e_type_int64(Value, Bin, _TrUserData) ->
    <<N:64/unsigned-native>> = <<Value:64/signed-native>>,
    e_varint(N, Bin).

-compile({nowarn_unused_function,e_type_bool/3}).
e_type_bool(true, Bin, _TrUserData) -> <<Bin/binary, 1>>;
e_type_bool(false, Bin, _TrUserData) -> <<Bin/binary, 0>>;
e_type_bool(1, Bin, _TrUserData) -> <<Bin/binary, 1>>;
e_type_bool(0, Bin, _TrUserData) -> <<Bin/binary, 0>>.

-compile({nowarn_unused_function,e_type_string/3}).
e_type_string(S, Bin, _TrUserData) ->
    Utf8 = unicode:characters_to_binary(S),
    Bin2 = e_varint(byte_size(Utf8), Bin),
    <<Bin2/binary, Utf8/binary>>.

-compile({nowarn_unused_function,e_type_bytes/3}).
e_type_bytes(Bytes, Bin, _TrUserData) when is_binary(Bytes) ->
    Bin2 = e_varint(byte_size(Bytes), Bin),
    <<Bin2/binary, Bytes/binary>>;
e_type_bytes(Bytes, Bin, _TrUserData) when is_list(Bytes) ->
    BytesBin = iolist_to_binary(Bytes),
    Bin2 = e_varint(byte_size(BytesBin), Bin),
    <<Bin2/binary, BytesBin/binary>>.

-compile({nowarn_unused_function,e_type_fixed32/3}).
e_type_fixed32(Value, Bin, _TrUserData) -> <<Bin/binary, Value:32/little>>.

-compile({nowarn_unused_function,e_type_sfixed32/3}).
e_type_sfixed32(Value, Bin, _TrUserData) -> <<Bin/binary, Value:32/little-signed>>.

-compile({nowarn_unused_function,e_type_fixed64/3}).
e_type_fixed64(Value, Bin, _TrUserData) -> <<Bin/binary, Value:64/little>>.

-compile({nowarn_unused_function,e_type_sfixed64/3}).
e_type_sfixed64(Value, Bin, _TrUserData) -> <<Bin/binary, Value:64/little-signed>>.

-compile({nowarn_unused_function,e_type_float/3}).
e_type_float(V, Bin, _) when is_number(V) -> <<Bin/binary, V:32/little-float>>;
e_type_float(infinity, Bin, _) -> <<Bin/binary, 0:16, 128, 127>>;
e_type_float('-infinity', Bin, _) -> <<Bin/binary, 0:16, 128, 255>>;
e_type_float(nan, Bin, _) -> <<Bin/binary, 0:16, 192, 127>>.

-compile({nowarn_unused_function,e_type_double/3}).
e_type_double(V, Bin, _) when is_number(V) -> <<Bin/binary, V:64/little-float>>;
e_type_double(infinity, Bin, _) -> <<Bin/binary, 0:48, 240, 127>>;
e_type_double('-infinity', Bin, _) -> <<Bin/binary, 0:48, 240, 255>>;
e_type_double(nan, Bin, _) -> <<Bin/binary, 0:48, 248, 127>>.

-compile({nowarn_unused_function,e_unknown_elems/2}).
e_unknown_elems([Elem | Rest], Bin) ->
    BinR = case Elem of
               {varint, FNum, N} ->
                   BinF = e_varint(FNum bsl 3, Bin),
                   e_varint(N, BinF);
               {length_delimited, FNum, Data} ->
                   BinF = e_varint(FNum bsl 3 bor 2, Bin),
                   BinL = e_varint(byte_size(Data), BinF),
                   <<BinL/binary, Data/binary>>;
               {group, FNum, GroupFields} ->
                   Bin1 = e_varint(FNum bsl 3 bor 3, Bin),
                   Bin2 = e_unknown_elems(GroupFields, Bin1),
                   e_varint(FNum bsl 3 bor 4, Bin2);
               {fixed32, FNum, V} ->
                   BinF = e_varint(FNum bsl 3 bor 5, Bin),
                   <<BinF/binary, V:32/little>>;
               {fixed64, FNum, V} ->
                   BinF = e_varint(FNum bsl 3 bor 1, Bin),
                   <<BinF/binary, V:64/little>>
           end,
    e_unknown_elems(Rest, BinR);
e_unknown_elems([], Bin) -> Bin.

-compile({nowarn_unused_function,e_varint/3}).
e_varint(N, Bin, _TrUserData) -> e_varint(N, Bin).

-compile({nowarn_unused_function,e_varint/2}).
e_varint(N, Bin) when N =< 127 -> <<Bin/binary, N>>;
e_varint(N, Bin) ->
    Bin2 = <<Bin/binary, (N band 127 bor 128)>>,
    e_varint(N bsr 7, Bin2).

is_empty_string("") -> true;
is_empty_string(<<>>) -> true;
is_empty_string(L) when is_list(L) -> not string_has_chars(L);
is_empty_string(B) when is_binary(B) -> false.

string_has_chars([C | _]) when is_integer(C) -> true;
string_has_chars([H | T]) ->
    case string_has_chars(H) of
        true -> true;
        false -> string_has_chars(T)
    end;
string_has_chars(B) when is_binary(B), byte_size(B) =/= 0 -> true;
string_has_chars(C) when is_integer(C) -> true;
string_has_chars(<<>>) -> false;
string_has_chars([]) -> false.


decode_msg(Bin, MsgName) when is_binary(Bin) -> decode_msg(Bin, MsgName, []).

decode_msg(Bin, MsgName, Opts) when is_binary(Bin) ->
    TrUserData = proplists:get_value(user_data, Opts),
    decode_msg_1_catch(Bin, MsgName, TrUserData).


decode_msg_1_catch(Bin, MsgName, TrUserData) ->
    try decode_msg_2_doit(MsgName, Bin, TrUserData)
    catch
        error:{gpb_error,_}=Reason:StackTrace ->
            erlang:raise(error, Reason, StackTrace);
        Class:Reason:StackTrace ->
            error({gpb_error,
                   {decoding_failure,
                    {Bin, MsgName, {Class, Reason, StackTrace}}}})
    end.

decode_msg_2_doit(test, Bin, TrUserData) -> id(decode_msg_test(Bin, TrUserData), TrUserData);
decode_msg_2_doit(phoneNumber, Bin, TrUserData) -> id(decode_msg_phoneNumber(Bin, TrUserData), TrUserData);
decode_msg_2_doit(comboLeaf, Bin, TrUserData) -> id(decode_msg_comboLeaf(Bin, TrUserData), TrUserData);
decode_msg_2_doit(benchLeaf, Bin, TrUserData) -> id(decode_msg_benchLeaf(Bin, TrUserData), TrUserData);
decode_msg_2_doit(tBenchScalar, Bin, TrUserData) -> id(decode_msg_tBenchScalar(Bin, TrUserData), TrUserData);
decode_msg_2_doit(tBenchList, Bin, TrUserData) -> id(decode_msg_tBenchList(Bin, TrUserData), TrUserData);
decode_msg_2_doit(tBenchMap, Bin, TrUserData) -> id(decode_msg_tBenchMap(Bin, TrUserData), TrUserData);
decode_msg_2_doit(tBenchOneof, Bin, TrUserData) -> id(decode_msg_tBenchOneof(Bin, TrUserData), TrUserData);
decode_msg_2_doit(tBenchNested, Bin, TrUserData) -> id(decode_msg_tBenchNested(Bin, TrUserData), TrUserData);
decode_msg_2_doit(tBenchHeavy, Bin, TrUserData) -> id(decode_msg_tBenchHeavy(Bin, TrUserData), TrUserData).



decode_msg_test(Bin, TrUserData) -> dfp_read_field_def_test(Bin, 0, 0, 0, id(<<>>, TrUserData), TrUserData).

dfp_read_field_def_test(<<10, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> d_field_test_aa(Rest, Z1, Z2, F, F@_1, TrUserData);
dfp_read_field_def_test(<<>>, 0, 0, _, F@_1, _) -> #test{aa = F@_1};
dfp_read_field_def_test(Other, Z1, Z2, F, F@_1, TrUserData) -> dg_read_field_def_test(Other, Z1, Z2, F, F@_1, TrUserData).

dg_read_field_def_test(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 32 - 7 -> dg_read_field_def_test(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
dg_read_field_def_test(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_test_aa(Rest, 0, 0, 0, F@_1, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_test(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                1 -> skip_64_test(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                2 -> skip_length_delimited_test(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                3 -> skip_group_test(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                5 -> skip_32_test(Rest, 0, 0, Key bsr 3, F@_1, TrUserData)
            end
    end;
dg_read_field_def_test(<<>>, 0, 0, _, F@_1, _) -> #test{aa = F@_1}.

d_field_test_aa(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_test_aa(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_test_aa(<<0:1, X:7, Rest/binary>>, N, Acc, F, _, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bytes:Len/binary, Rest2/binary>> = Rest, Bytes2 = binary:copy(Bytes), {id(Bytes2, TrUserData), Rest2} end,
    dfp_read_field_def_test(RestF, 0, 0, F, NewFValue, TrUserData).

skip_varint_test(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> skip_varint_test(Rest, Z1, Z2, F, F@_1, TrUserData);
skip_varint_test(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_test(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_length_delimited_test(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> skip_length_delimited_test(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
skip_length_delimited_test(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) ->
    Length = X bsl N + Acc,
    <<_:Length/binary, Rest2/binary>> = Rest,
    dfp_read_field_def_test(Rest2, 0, 0, F, F@_1, TrUserData).

skip_group_test(Bin, _, Z2, FNum, F@_1, TrUserData) ->
    {_, Rest} = read_group(Bin, FNum),
    dfp_read_field_def_test(Rest, 0, Z2, FNum, F@_1, TrUserData).

skip_32_test(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_test(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_64_test(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_test(Rest, Z1, Z2, F, F@_1, TrUserData).

decode_msg_phoneNumber(Bin, TrUserData) -> dfp_read_field_def_phoneNumber(Bin, 0, 0, 0, id(undefined, TrUserData), id(0, TrUserData), TrUserData).

dfp_read_field_def_phoneNumber(<<10, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_phoneNumber_number(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
dfp_read_field_def_phoneNumber(<<16, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_phoneNumber_type(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
dfp_read_field_def_phoneNumber(<<>>, 0, 0, _, F@_1, F@_2, _) -> #phoneNumber{number = F@_1, type = F@_2};
dfp_read_field_def_phoneNumber(Other, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dg_read_field_def_phoneNumber(Other, Z1, Z2, F, F@_1, F@_2, TrUserData).

dg_read_field_def_phoneNumber(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 32 - 7 -> dg_read_field_def_phoneNumber(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
dg_read_field_def_phoneNumber(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, F@_2, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_phoneNumber_number(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        16 -> d_field_phoneNumber_type(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_phoneNumber(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                1 -> skip_64_phoneNumber(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                2 -> skip_length_delimited_phoneNumber(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                3 -> skip_group_phoneNumber(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                5 -> skip_32_phoneNumber(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData)
            end
    end;
dg_read_field_def_phoneNumber(<<>>, 0, 0, _, F@_1, F@_2, _) -> #phoneNumber{number = F@_1, type = F@_2}.

d_field_phoneNumber_number(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> d_field_phoneNumber_number(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
d_field_phoneNumber_number(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, F@_2, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_test(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_phoneNumber(RestF,
                                   0,
                                   0,
                                   F,
                                   if Prev == undefined -> NewFValue;
                                      true -> merge_msg_test(Prev, NewFValue, TrUserData)
                                   end,
                                   F@_2,
                                   TrUserData).

d_field_phoneNumber_type(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> d_field_phoneNumber_type(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
d_field_phoneNumber_type(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, _, TrUserData) ->
    {NewFValue, RestF} = {begin <<Res:32/signed-native>> = <<(X bsl N + Acc):32/unsigned-native>>, id(Res, TrUserData) end, Rest},
    dfp_read_field_def_phoneNumber(RestF, 0, 0, F, F@_1, NewFValue, TrUserData).

