verify_msg(Msg) when tuple_size(Msg) >= 1 -> verify_msg(Msg, element(1, Msg), []);
verify_msg(X) -> mk_type_error(not_a_known_message, X, []).

verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []);
verify_msg(Msg, Opts) when tuple_size(Msg) >= 1, is_list(Opts) -> verify_msg(Msg, element(1, Msg), Opts);
verify_msg(X, _Opts) -> mk_type_error(not_a_known_message, X, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        test -> v_msg_test(Msg, [MsgName], TrUserData);
        phoneNumber -> v_msg_phoneNumber(Msg, [MsgName], TrUserData);
        comboLeaf -> v_msg_comboLeaf(Msg, [MsgName], TrUserData);
        benchLeaf -> v_msg_benchLeaf(Msg, [MsgName], TrUserData);
        tBenchScalar -> v_msg_tBenchScalar(Msg, [MsgName], TrUserData);
        tBenchList -> v_msg_tBenchList(Msg, [MsgName], TrUserData);
        tBenchMap -> v_msg_tBenchMap(Msg, [MsgName], TrUserData);
        tBenchOneof -> v_msg_tBenchOneof(Msg, [MsgName], TrUserData);
        tBenchNested -> v_msg_tBenchNested(Msg, [MsgName], TrUserData);
        tBenchHeavy -> v_msg_tBenchHeavy(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


