%% Convert a service name and an rpc name, both as atoms,
%% to a fully qualified (ie with package name) service name and
%% an rpc name as binaries.
-spec service_and_rpc_name_to_fqbins(_, _) -> no_return().
service_and_rpc_name_to_fqbins(S, R) -> error({gpb_error, {badservice_or_rpc, {S, R}}}).


fqbin_to_msg_name(<<"test">>) -> test;
fqbin_to_msg_name(<<"phoneNumber">>) -> phoneNumber;
fqbin_to_msg_name(<<"comboLeaf">>) -> comboLeaf;
fqbin_to_msg_name(<<"benchLeaf">>) -> benchLeaf;
fqbin_to_msg_name(<<"tBenchScalar">>) -> tBenchScalar;
fqbin_to_msg_name(<<"tBenchList">>) -> tBenchList;
fqbin_to_msg_name(<<"tBenchMap">>) -> tBenchMap;
fqbin_to_msg_name(<<"tBenchOneof">>) -> tBenchOneof;
fqbin_to_msg_name(<<"tBenchNested">>) -> tBenchNested;
fqbin_to_msg_name(<<"tBenchHeavy">>) -> tBenchHeavy;
fqbin_to_msg_name(E) -> error({gpb_error, {badmsg, E}}).


msg_name_to_fqbin(test) -> <<"test">>;
msg_name_to_fqbin(phoneNumber) -> <<"phoneNumber">>;
msg_name_to_fqbin(comboLeaf) -> <<"comboLeaf">>;
msg_name_to_fqbin(benchLeaf) -> <<"benchLeaf">>;
msg_name_to_fqbin(tBenchScalar) -> <<"tBenchScalar">>;
msg_name_to_fqbin(tBenchList) -> <<"tBenchList">>;
msg_name_to_fqbin(tBenchMap) -> <<"tBenchMap">>;
msg_name_to_fqbin(tBenchOneof) -> <<"tBenchOneof">>;
msg_name_to_fqbin(tBenchNested) -> <<"tBenchNested">>;
msg_name_to_fqbin(tBenchHeavy) -> <<"tBenchHeavy">>;
msg_name_to_fqbin(E) -> error({gpb_error, {badmsg, E}}).


-spec fqbin_to_enum_name(_) -> no_return().
fqbin_to_enum_name(E) -> error({gpb_error, {badenum, E}}).


-spec enum_name_to_fqbin(_) -> no_return().
enum_name_to_fqbin(E) -> error({gpb_error, {badenum, E}}).


get_package_name() -> undefined.


%% Whether or not the message names
%% are prepended with package name or not.
uses_packages() -> false.


source_basename() -> "bench_heavy.proto".


%% Retrieve all proto file names, also imported ones.
%% The order is top-down. The first element is always the main
%% source file. The files are returned with extension,
%% see get_all_proto_names/0 for a version that returns
%% the basenames sans extension
get_all_source_basenames() -> ["bench_heavy.proto"].


%% Retrieve all proto file names, also imported ones.
%% The order is top-down. The first element is always the main
%% source file. The files are returned sans .proto extension,
%% to make it easier to use them with the various get_xyz_containment
%% functions.
get_all_proto_names() -> ["bench_heavy"].


get_msg_containment("bench_heavy") -> [benchLeaf, comboLeaf, phoneNumber, tBenchHeavy, tBenchList, tBenchMap, tBenchNested, tBenchOneof, tBenchScalar, test];
get_msg_containment(P) -> error({gpb_error, {badproto, P}}).


get_pkg_containment("bench_heavy") -> undefined;
get_pkg_containment(P) -> error({gpb_error, {badproto, P}}).


get_service_containment("bench_heavy") -> [];
get_service_containment(P) -> error({gpb_error, {badproto, P}}).


get_rpc_containment("bench_heavy") -> [];
get_rpc_containment(P) -> error({gpb_error, {badproto, P}}).


get_enum_containment("bench_heavy") -> [];
get_enum_containment(P) -> error({gpb_error, {badproto, P}}).


get_proto_by_msg_name_as_fqbin(<<"test">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"phoneNumber">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"comboLeaf">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"benchLeaf">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"tBenchScalar">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"tBenchList">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"tBenchMap">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"tBenchOneof">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"tBenchNested">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(<<"tBenchHeavy">>) -> "bench_heavy";
get_proto_by_msg_name_as_fqbin(E) -> error({gpb_error, {badmsg, E}}).


-spec get_proto_by_service_name_as_fqbin(_) -> no_return().
get_proto_by_service_name_as_fqbin(E) -> error({gpb_error, {badservice, E}}).


-spec get_proto_by_enum_name_as_fqbin(_) -> no_return().
get_proto_by_enum_name_as_fqbin(E) -> error({gpb_error, {badenum, E}}).


-spec get_protos_by_pkg_name_as_fqbin(_) -> no_return().
get_protos_by_pkg_name_as_fqbin(E) -> error({gpb_error, {badpkg, E}}).



